import sys
sys.path.insert(0, "/workspace")
from docopt import docopt, DocoptExit, DocoptLanguageError

results = []
def check(name, fn):
    try:
        fn()
        results.append((name, "PASS", ""))
    except AssertionError as e:
        results.append((name, "FAIL", str(e)))
    except Exception as e:
        results.append((name, "ERROR", f"{type(e).__name__}: {e}"))

def node1():
    doc = """
Usage:
  prog.py [-h] [--version] <input> [--output=<file>]
Options:
  -h --help         Show help.
  --version         Show version.
  --output=<file>   Output file.
"""
    r = docopt(doc, argv=["input.txt", "--output=out.txt"])
    assert r == {'<input>': 'input.txt', '--output': 'out.txt', '--help': False, '--version': False}, r

def node2():
    doc = """
Usage: prog.py [--repeat=<n>] <file>...
Options:
  --repeat=<n>  Repeat count [default: 1].
"""
    r = docopt(doc, argv=["file1.txt", "file2.txt", "--repeat=3"])
    assert r == {'<file>': ['file1.txt', 'file2.txt'], '--repeat': '3'}, r

def node3():
    doc = """
Usage:
  git add <file>...
  git commit -m <msg>
  git push [origin] [master]
"""
    r = docopt(doc, argv=["commit", "-m", "init"])
    assert r == {'add': False, 'commit': True, 'push': False, '<file>': None,
                 '-m': True, '<msg>': 'init', 'origin': False, 'master': False}, r

def node4():
    doc = "Usage: prog.py [-a] [-b] [-c]"
    r = docopt(doc, argv=["-abc"])
    assert r == {'-a': True, '-b': True, '-c': True}, r

def node5():
    doc = """
Usage: prog.py [--version]
Options:
  --version  Show version.
"""
    try:
        docopt(doc, argv=["--version"], version="1.0.0")
        assert False, "no exit"
    except SystemExit:
        pass

def node6():
    doc = "Usage: prog.py <input>"
    try:
        docopt(doc, argv=[])
        assert False
    except SystemExit as e:
        assert "Usage: prog.py <input>" in str(e), str(e)

def node7():
    doc = """
Usage: prog.py [--count=<n>]
Options:
  --count=<n>  Count [default: 5].
"""
    r = docopt(doc, argv=[])
    assert r == {'--count': '5'}, r

def node8():
    doc = "Usage: prog.py (go | stop) [--speed=<s>]"
    r = docopt(doc, argv=["go", "--speed=10"])
    assert r == {'go': True, 'stop': False, '--speed': '10'}, r

def node10():
    doc = """
Usage: prog.py [options]
Options:
  -h --help
  --foo
"""
    r = docopt(doc, argv=["--foo"])
    print("node10:", r)

def node11a():
    doc = """
Usage: prog [options]
Options: --version  Show version.
         --verbose  Verbose mode.
"""
    r = docopt(doc, argv=["--ver"])
    assert r == {"--version": True, "--verbose": False}, r

def node11b():
    doc = """
Usage: prog [options]
Options: --version  Show version.
         --verbose  Verbose mode.
"""
    try:
        docopt(doc, argv=["--v"])
        assert False, "no error"
    except SystemExit:
        pass

def node12():
    doc = "Usage: prog [-v -v]"
    assert docopt(doc, argv=[]) == {"-v": 0}
    assert docopt(doc, argv=["-v"]) == {"-v": 1}
    assert docopt(doc, argv=["-vv"]) == {"-v": 2}
    doc = "Usage: prog NAME..."
    assert docopt(doc, argv=["a", "b"]) == {"NAME": ["a", "b"]}

def node13():
    doc = "Usage: prog (-a|-b)"
    assert docopt(doc, argv=["-a"]) == {"-a": True, "-b": False}
    assert docopt(doc, argv=["-b"]) == {"-a": False, "-b": True}
    try:
        docopt(doc, argv=["-a", "-b"])
        assert False
    except SystemExit:
        pass

