    doc = "Usage: prog [options]\nOptions: -p PATH [default: ./]"
    r = docopt(doc, argv=[])
    assert r == {"-p": "./"}, r
    doc = "Usage: prog [-o <o>]...\nOptions: -o <o> [default: x y]"
    r = docopt(doc, argv=[])
    assert r == {"-o": ["x", "y"]}, r

def node15():
    doc = "Usage: prog <arg>"
    try:
        docopt(doc, argv=[])
        assert False
    except DocoptExit:
        pass

def node16():
    doc = "Usage: prog [-vqrd] [FILE]\nOptions:\n  -d --dash-arg\n  -v\n  -q\n  -r\n"
    args = docopt(doc, argv=["-v", "-d", "file.py"])
    assert args.v, args
    assert args.dash_arg, args

