"""Tests derived from the docopt-ng specification examples.

These cover the typical usage scenarios: basic parsing, type inference,
subcommands, option stacking, help/version handling, error reporting,
defaults, complex patterns, dot-access, docstring linting, POSIX `--`,
and multi-usage branching.
"""
from __future__ import annotations

import pytest

import docopt
from docopt import docopt as docopt_fn
from docopt import DocoptExit
from docopt import DocoptLanguageError
from docopt import ParsedOptions
from docopt import _Argument
from docopt import _Command
from docopt import _Either
from docopt import _formal_usage
from docopt import _lint_docstring
from docopt import _NotRequired
from docopt import _OneOrMore
from docopt import _Option
from docopt import _OptionsShortcut
from docopt import _parse_argv
from docopt import _parse_docstring_sections
from docopt import _parse_longer
from docopt import _parse_options
from docopt import _parse_pattern
from docopt import _parse_shorts
from docopt import _Required
from docopt import _Tokens
from docopt import _transform


def test_api_importable():
    """The documented API surface is importable from the package root."""
    assert callable(docopt_fn)
    assert issubclass(DocoptExit, SystemExit)
    assert issubclass(DocoptLanguageError, Exception)
    assert issubclass(_Argument, docopt._LeafPattern)
    assert issubclass(_Command, _Argument)
    assert issubclass(_Option, docopt._LeafPattern)
    for cls in (_Either, _Required, _NotRequired, _OneOrMore, _OptionsShortcut):
        assert issubclass(cls, docopt._BranchPattern)
    for fn in (
        _parse_argv,
        _parse_docstring_sections,
        _parse_longer,
        _parse_options,
        _parse_pattern,
        _parse_shorts,
        _formal_usage,
        _lint_docstring,
        _transform,
    ):
        assert callable(fn)
    assert _Tokens is not None
    assert ParsedOptions is not None


def test_version():
    assert docopt.__version__ == "0.9.0"


def test_basic_parsing():
    doc = """
Usage:
  prog.py [-h] [--version] <input> [--output=<file>]
Options:
  -h --help         Show help.
  --version         Show version.
  --output=<file>   Output file.
"""
    result = docopt_fn(doc, argv=["input.txt", "--output=out.txt"])
    assert result == {
        "<input>": "input.txt",
        "--output": "out.txt",
        "--help": False,
        "--version": False,
    }


def test_type_inference_repeatable_argument():
    doc = """
Usage: prog.py [--repeat=<n>] <file>...
Options:
  --repeat=<n>  Repeat count [default: 1].
"""
    result = docopt_fn(doc, argv=["file1.txt", "file2.txt", "--repeat=3"])
    assert result == {"<file>": ["file1.txt", "file2.txt"], "--repeat": "3"}


def test_subcommands():
    doc = """
Usage:
  git add <file>...
  git commit -m <msg>
  git push [origin] [master]
"""
    result = docopt_fn(doc, argv=["commit", "-m", "init"])
    assert result == {
        "add": False,
        "commit": True,
        "push": False,
        "<file>": [],
        "-m": True,
        "<msg>": "init",
        "origin": False,
        "master": False,
    }


def test_short_option_stacking():
    doc = "Usage: prog.py [-a] [-b] [-c]"
    assert docopt_fn(doc, argv=["-abc"]) == {"-a": True, "-b": True, "-c": True}


def test_short_option_with_stacked_value():
    doc = "Usage: prog -p PATH\nOptions: -p PATH"
    assert docopt_fn(doc, argv=["-pHOME"]) == {"-p": "HOME"}


def test_version_auto_handling(capsys):
    doc = """
Usage: prog.py [--version]
Options:
  --version  Show version.
"""
    with pytest.raises(SystemExit):
        docopt_fn(doc, argv=["--version"], version="1.0.0")
    assert capsys.readouterr().out.strip() == "1.0.0"


def test_help_auto_handling(capsys):
    doc = "Usage: prog.py [-h]\nOptions:\n  -h --help  Show help."
    with pytest.raises(SystemExit) as exc_info:
        docopt_fn(doc, argv=["--help"])
    assert exc_info.value.code is None
    assert "Usage: prog.py [-h]" in capsys.readouterr().out


def test_missing_argument_error():
    doc = "Usage: prog.py <input>"
    with pytest.raises(SystemExit) as exc_info:
        docopt_fn(doc, argv=[])
    assert str(exc_info.value) == "Usage: prog.py <input>"


def test_default_value():
    doc = """
Usage: prog.py [--count=<n>]
Options:
  --count=<n>  Count [default: 5].
"""
    assert docopt_fn(doc, argv=[]) == {"--count": "5"}


def test_complex_pattern():
    doc = "Usage: prog.py (go | stop) [--speed=<s>]"
    assert docopt_fn(doc, argv=["go", "--speed=10"]) == {
        "go": True,
        "stop": False,
        "--speed": "10",
    }


def test_options_shortcut():
    doc = """
Usage: prog.py [options]
Options:
  -h --help
  --foo
"""
    assert docopt_fn(doc, argv=["--foo"]) == {"--help": False, "--foo": True}


def test_unique_prefix_expansion():
    doc = """
Usage: prog [options]
Options: --version  Show version.
         --verbose  Verbose mode.
"""
    assert docopt_fn(doc, argv=["--vers"]) == {"--version": True, "--verbose": False}
    assert docopt_fn(doc, argv=["--verb"]) == {"--version": False, "--verbose": True}


def test_ambiguous_prefix_errors():
    doc = """
Usage: prog [options]
Options: --version  Show version.
         --verbose  Verbose mode.
"""
    with pytest.raises(SystemExit):
        docopt_fn(doc, argv=["--v"])


def test_flag_counting():
    doc = "Usage: prog [-v -v]"
    assert docopt_fn(doc, argv=[]) == {"-v": 0}
    assert docopt_fn(doc, argv=["-v"]) == {"-v": 1}
    assert docopt_fn(doc, argv=["-vv"]) == {"-v": 2}


def test_repeated_argument_list():
    doc = "Usage: prog NAME..."
    assert docopt_fn(doc, argv=["a", "b"]) == {"NAME": ["a", "b"]}


def test_mutual_exclusion():
    doc = "Usage: prog (-a|-b)"
    assert docopt_fn(doc, argv=["-a"]) == {"-a": True, "-b": False}
    assert docopt_fn(doc, argv=["-b"]) == {"-a": False, "-b": True}
    with pytest.raises(SystemExit):
